class Solution {
    static constexpr long long MOD = 1e9 + 7;
    long long pw(long long b, long long e) {
        long long r = 1; b %= MOD;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
public:
    int countKSubsequencesWithMaxBeauty(string s, int k) {
        int cnt[26] = {};
        for (char c : s) cnt[c - 'a']++;
        vector<int> v;
        for (int c : cnt) if (c) v.push_back(c);
        if (k > (int)v.size()) return 0;
        sort(v.rbegin(), v.rend());
        int base = v[k - 1];
        long long ans = 1; int full = 0, tie = 0;
        for (int c : v) {
            if (c > base) { ans = ans * pw(c, c) % MOD; full++; }
            else if (c == base) tie++;
        }
        int need = k - full;
        ans = ans * pw(base, need) % MOD;
        long long num = 1, den = 1;
        for (int i = 0; i < need; i++) { num = num * ((tie - i) % MOD) % MOD; den = den * (i + 1) % MOD; }
        ans = ans * num % MOD * pw(den, MOD - 2) % MOD;
        return ans;
    }
};

