class Solution {
    static final long MOD = 1_000_000_007L;
    long pw(long b, long e) {
        long r = 1; b %= MOD;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    public int countKSubsequencesWithMaxBeauty(String s, int k) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        List<Integer> v = new ArrayList<>();
        for (int c : cnt) if (c > 0) v.add(c);
        if (k > v.size()) return 0;
        v.sort(java.util.Collections.reverseOrder());
        int base = v.get(k - 1), full = 0, tie = 0;
        long ans = 1;
        for (int c : v) {
            if (c > base) { ans = ans * pw(c, c) % MOD; full++; }
            else if (c == base) tie++;
        }
        int need = k - full;
        ans = ans * pw(base, need) % MOD;
        long num = 1, den = 1;
        for (int i = 0; i < need; i++) { num = num * ((tie - i) % MOD) % MOD; den = den * (i + 1) % MOD; }
        ans = ans * num % MOD * pw(den, MOD - 2) % MOD;
        return (int) ans;
    }
}

