var countKSubsequencesWithMaxBeauty = function(s, k) {
    const MOD = 1e9 + 7;
    const pw = (b, e) => { let r = 1n; b = BigInt(b) % BigInt(MOD); const E = BigInt(e); let ee = E; while (ee > 0n) { if (ee & 1n) r = r * b % BigInt(MOD); b = b * b % BigInt(MOD); ee >>= 1n; } return Number(r); };
    const cnt = Array(26).fill(0);
    for (const c of s) cnt[c.charCodeAt(0) - 97]++;
    const v = cnt.filter(c => c > 0).sort((a, b) => b - a);
    if (k > v.length) return 0;
    const base = v[k - 1];
    let ans = pw(base, k - v.filter(c => c > base).length);
    let full = 0, tie = 0;
    for (const c of v) { if (c > base) { ans = ans * pw(c, c) % MOD; full++; } else if (c === base) tie++; }
    const need = k - full;
    let num = 1, den = 1;
    for (let i = 0; i < need; i++) { num = num * ((tie - i) % MOD) % MOD; den = den * (i + 1) % MOD; }
    const inv = (x) => { let r = 1n, b = BigInt(x), e = BigInt(MOD - 2); while (e > 0n) { if (e & 1n) r = r * b % BigInt(MOD); b = b * b % BigInt(MOD); e >>= 1n; } return Number(r); };
    return ans * num % MOD * inv(den) % MOD;
};
